#!/usr/bin/env bash
# Builds the workspace before the agent starts. claude plugin eval runs it
# only under --scaffold, with the empty workspace as the working directory.
set -euo pipefail
printf '%s' 'IiIiU21hbGwgc2NoZWR1bGluZyBoZWxwZXJzLiIiIgoKREFZX1NFQ09ORFMgPSA4NjQwMAo=' | base64 -d > sched_helpers.py
printf '%s' 'aW1wb3J0IHNjaGVkX2hlbHBlcnMKCmFzc2VydCBzY2hlZF9oZWxwZXJzLkRBWV9TRUNPTkRTID09IDg2NDAwCnByaW50KCJvayIpCg==' | base64 -d > test_sched.py
git init -q 2>/dev/null || true
git add -A 2>/dev/null || true
git -c user.email=e@e -c user.name=e commit -qm 'baseline: scheduling helpers module' 2>/dev/null || true
printf '%s' '' | base64 -d > sched_helpers.py
printf '%s' '' | base64 -d > test_sched.py
git add -A 2>/dev/null || true
git -c user.email=e@e -c user.name=e commit -qm 'add duration parsing, memoization, backoff and day alignment' 2>/dev/null || true
